-- V69 — TankerInbound: reuse the existing "Dispatch Vehicle Details" page
-- (aria:dispatch-vehicle-details, built for TankerOutbound in V57/V62)
-- instead of the older generic aria:dispatch-vehicle-entry. Opens up the
-- ownership/driver/broker/invoice/vendor/oil-RM/tanker-number/PO-approval
-- fields already on that page to the M10.TankerInbound flow variant too.

-- 1. Point both TankerInbound transitions at the richer page.
UPDATE workflow_definition
   SET body_json = REPLACE(body_json,
         '"pageCode":"aria:dispatch-vehicle-entry"',
         '"pageCode":"aria:dispatch-vehicle-details"')
 WHERE code = 'M10.TankerInbound' AND status = 'PUBLISHED';

-- 2. Extend the page's variant-scoped fields to also show for TankerInbound.
UPDATE page_version pv
  JOIN page_definition pd ON pd.id = pv.page_id
   SET pv.body_json = '{"kind": "layout", "schemaVersion": 2, "dataSources": [{"id": "dispatchQueue", "kind": "rest", "method": "GET", "url": "/api/workflow/queue/Dispatch"}], "layout": [{"kind": "Section", "title": "Dispatch Queue (Open)", "fields": [{"kind": "WorkflowQueueList", "persona": "Dispatch", "dataSource": "dispatchQueue", "pageSize": 25, "cardFields": ["vehicleNo", "gpNumber", "flowVariant", "currentState"]}]}, {"kind": "Section", "title": "Vehicle & Dispatch Details", "fields": [{"kind": "FormField", "type": "select", "name": "vehicleNo", "label": "Vehicle Number", "required": true, "placeholder": "Select vehicle awaiting dispatch entry", "optionsSource": {"type": "datasource", "spec": {"type": "entity", "entity": "GatePass", "joins": [{"entity": "WorkflowInstance", "as": "wi", "on": "gate_pass.workflow_instance_id = wi.id"}], "filter": {"and": [{"field": "wi.assigned_role", "op": "eq", "value": "Dispatch"}, {"field": "wi.status", "op": "eq", "value": "OPEN"}]}, "select": ["id", "vehicle_no"], "sort": [{"field": "vehicle_no", "dir": "asc"}]}, "valueField": "vehicle_no", "labelField": "vehicle_no"}, "onChangeFill": {"flowVariantCode": "flow_variant_code", "loadingType": "loading_type", "instanceId": "workflow_instance_id"}}, {"kind": "FormField", "type": "text", "name": "flowVariantCode", "label": "Flow Variant", "disabled": true}, {"kind": "FormField", "type": "text", "name": "loadingType", "label": "Loading Type", "disabled": true}, {"kind": "FormField", "type": "text", "name": "instanceId", "label": "Workflow Instance", "disabled": true}, {"kind": "FormField", "type": "select", "name": "ownershipType", "label": "Ownership", "options": ["OWN VEHICLE", "HIRED VEHICLE"]}, {"kind": "FormField", "type": "text", "name": "driverName", "label": "Driver Name"}, {"kind": "FormField", "type": "text", "name": "driverPhone", "label": "Driver Contact"}, {"kind": "FormField", "type": "text", "name": "brokerName", "label": "Broker Details", "visibleWhen": "#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\'"}, {"kind": "FormField", "type": "text", "name": "invoiceNo", "label": "Invoice No", "visibleWhen": "#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\'"}, {"kind": "FormField", "type": "number", "name": "invoiceQty", "label": "Invoice Qty", "visibleWhen": "#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\'"}, {"kind": "FormField", "type": "text", "name": "vendorName", "label": "Vendor Details", "visibleWhen": "#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\'"}, {"kind": "FormField", "type": "text", "name": "oilRmItem", "label": "Oil RM Details", "visibleWhen": "#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\'"}, {"kind": "FormField", "type": "text", "name": "tankerNo", "label": "Tanker Number", "visibleWhen": "#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\'"}, {"kind": "FormField", "type": "select", "name": "poVerified", "label": "PO Verified", "options": ["YES", "NO - MANAGER APPROVAL"], "visibleWhen": "#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\'"}, {"kind": "FormField", "type": "text", "name": "poOverrideReason", "label": "Reason (if PO not verified)", "visibleWhen": "(#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\') && #form.poVerified != \'YES\'", "requiredWhen": "(#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\') && #form.poVerified != \'YES\'"}, {"kind": "FormField", "type": "text", "name": "dispatchOfficerName", "label": "Dispatch Front Officer Name", "visibleWhen": "#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\'"}, {"kind": "FormField", "type": "text", "name": "transportName", "label": "Transport Name", "visibleWhen": "#form.flowVariantCode == \'M10.PackLoading\' || #form.flowVariantCode == \'M10.FGLoading\' || #form.flowVariantCode == \'M10.TankerOutbound\'"}, {"kind": "FormField", "type": "textarea", "name": "packingFgStockDetails", "label": "Packing / FG Stock Details", "visibleWhen": "#form.flowVariantCode == \'M10.PackLoading\' || #form.flowVariantCode == \'M10.FGLoading\'"}, {"kind": "WorkflowActionButton", "label": "Save Vehicle Details", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "variant": "primary"}]}], "entity": "DispatchVehicleDetail"}'
 WHERE pd.code = 'aria:dispatch-vehicle-details' AND pv.status = 'PUBLISHED';
